+	// A built-in agent name to look for in both listings.
+	builtins := agent.AvailableNames()
+	if len(builtins) == 0 {
+		t.Skip("no built-in agents registered in this build")
+	}
+	builtin := builtins[0]
+
+	repoDir := t.TempDir()
+	testutil.InitRepo(t, repoDir)
